def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    min_diff = float('inf')
    closest_pair = ()
    for pair in itertools.combinations(numbers, 2):
        diff = abs(pair[0] - pair[1])
        if diff < min_diff:
            min_diff = diff
            closest_pair = pair
        elif diff == min_diff:
            if pair[0] < closest_pair[0] or (pair[0] == closest_pair[0] and pair[1] < closest_pair[1]):
